BEGIN;
CREATE TABLE IF NOT EXISTS "LeaveRequests" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EmployeeId" integer NOT NULL REFERENCES "Employees" ("Id") ON DELETE RESTRICT,
    "StartDate" date NOT NULL,
    "EndDate" date NOT NULL,
    "LeaveType" varchar(30) NOT NULL,
    "Reason" varchar(1000) NOT NULL,
    "Status" varchar(20) NOT NULL,
    "ManagerComment" varchar(500),
    "ReviewedByUserId" integer,
    "ReviewedAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_LeaveRequests_EmployeeId_StartDate_EndDate"
ON "LeaveRequests" ("EmployeeId", "StartDate", "EndDate");
COMMIT;
